import{_ as t,o as e,c as s,a5 as n}from"./chunks/framework.DJo0M80U.js";const C=JSON.parse('{"title":"1. C 是什么以及为什么它仍然很重要","description":"The Little Book of C 中文版 — 1. C 是什么以及为什么它仍然很重要","frontmatter":{"title":"1. C 是什么以及为什么它仍然很重要","date":"2026-07-04","lang":"zh-CN","categories":["C 教程"],"tags":["C","Little Book of C","01-入门","中文"],"description":"The Little Book of C 中文版 — 1. C 是什么以及为什么它仍然很重要","source":"https://little-book-of.github.io/c/books/en-US/book.html","license":"CC BY-NC-SA 4.0","originalAuthor":"Duc-Tam Nguyen","translator":"机器辅助翻译（Google Translate）","section":1,"sidebarWeight":1,"alternateZh":"/posts/c教程/zh-CN/01-入门/001-What C Is and Why It Still Matters","alternateEn":"/posts/c教程/en-US/01-Getting Started/001-What C Is and Why It Still Matters"},"headers":[],"relativePath":"posts/c教程/zh-CN/01-入门/001-What C Is and Why It Still Matters.md","filePath":"posts/c教程/zh-CN/01-入门/001-What C Is and Why It Still Matters.md","lastUpdated":1790163617000}'),o={name:"posts/c教程/zh-CN/01-入门/001-What C Is and Why It Still Matters.md"};function l(i,a,p,c,h,d){return e(),s("div",null,[...a[0]||(a[0]=[n(`<p>[English version](/posts/c教程/en-US/01-Getting Started/001-What C Is and Why It Still Matters)</p><p>C 语言是最接近机器的语言，同时仍具有人类编写的感觉。它不是最新的或最简单的，但它是最强大的之一。每个现代操作系统、编译器和数据库都有一个用 C 编写的核心，从 Linux 和 Git 到 Python 的解释器，甚至浏览器的一部分。</p><p>学习 C 语言可以给你带来其他语言无法提供的东西：了解计算机的实际工作原理。您将看到如何管理内存、如何移动数据、CPU 如何运行代码，以及您编写的所有内容如何变成机器可以理解的微小指令。</p><p>C 教导纪律。没有垃圾收集器或安全网。您可以决定何时分配内存、何时释放内存以及忘记时会发生什么。您将学习精确性和控制力，这些技能可以成为任何语言的优秀程序员。</p><h4 id="小代码" tabindex="-1">小代码 <a class="header-anchor" href="#小代码" aria-label="Permalink to &quot;小代码&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>int main(void) {</span></span>
<span class="line"><span>    printf(&quot;Hello, C World!\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>运行这个程序，您就完成了每个 C 程序员开始做的事情，将第一行文本打印到屏幕上。它虽小，但却承载着 C 语言的精神：直接、明确、清晰。</p><h4 id="为什么它很重要" tabindex="-1">为什么它很重要 <a class="header-anchor" href="#为什么它很重要" aria-label="Permalink to &quot;为什么它很重要&quot;">​</a></h4><p>C 是所有系统编程的基础。当你理解它时，高级语言就更有意义了。您将了解编译器为何如此工作、为何会发生内存错误以及性能决策如何影响整个程序。</p><p>即使您从未编写过生产型 C 代码，它所建立的思维方式、仔细的推理、对细节的关注、对机器的尊重，也会影响您用任何语言编写代码的方式。</p><h4 id="自己尝试一下" tabindex="-1">自己尝试一下 <a class="header-anchor" href="#自己尝试一下" aria-label="Permalink to &quot;自己尝试一下&quot;">​</a></h4><p>安装 C 编译器，例如<code>gcc</code>或者<code>clang</code>.</p><p>将上面的代码保存到一个名为<code>hello.c</code>.</p><p>编译它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gcc hello.c -o hello</span></span></code></pre></div><p>运行它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>./hello</span></span></code></pre></div><p>修改消息并尝试打印更多行。您刚刚构建了第一个 C 程序。</p>`,18)])])}const u=t(o,[["render",l]]);export{C as __pageData,u as default};
